using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace LoopPedal {
static class NewFxChecks {
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 public static void Run(){var log=new List<string>();try{
 for(int preset=0;preset<4;preset++){var mode=new MasterFx{ReverbMode=2,PsxPreset=preset,Reverb=1};float l,r;for(int i=0;i<48000;i++)mode.Process(0,0,out l,out r);double e=0;for(int i=0;i<144000;i++){mode.Process(i==0?.4f:0,0,out l,out r);Check(!float.IsNaN(l)&&Math.Abs(l)<2,"PS1 program");e+=l*l+r*r;}Check(e>.00001,"PS1 preset silent");log.Add("PASS PS1 program "+preset+" energy="+e);}
 var advanced=new MasterFx();for(int id=26;id<36;id++){ExtraFx.set(advanced,id,.73f);Check(Math.Abs(ExtraFx.get(advanced.Copy(),id)-ExtraFx.get(advanced,id))<1e-6,"Advanced export copy");}advanced.ResetDefaults();for(int id=26;id<36;id++)Check(Math.Abs(ExtraFx.get(advanced,id)-ExtraFx.initial(id))<1e-5,"Advanced defaults");
 double[] tails=new double[3];for(int s=0;s<3;s++){var f=new MasterFx{ReverbMode=2,Reverb=1,Size=s*.5f};float l,r;for(int i=0;i<48000;i++)f.Process(0,0,out l,out r);double energy=0,late=0,peak=0,side=0;for(int i=0;i<480000;i++){f.Process(i==0?.5f:0,0,out l,out r);Check(!float.IsNaN(l)&&!float.IsInfinity(l),"PS1 finite");energy+=l*l+r*r;if(i>48000)late+=l*l+r*r;side+=Math.Abs(l-r);peak=Math.Max(peak,Math.Max(Math.Abs(l),Math.Abs(r)));}tails[s]=late;Check(energy>.0001&&side>.01&&peak<1,"PS1 stereo character");log.Add("PASS PS1 decay="+s*.5+" energy="+energy+" late="+late+" peak="+peak);}
 Check(tails[2]>tails[0]*10,"PS1 decay range");
 var crystal=new MasterFx{DelayMode=3,Delay=1,DelaySync=false,Time=.2f,Feedback=0};double fr=0,fi=0,cr=0,ci=0,stereo=0;for(int i=0;i<144000;i++){float l,r;crystal.Process((float)(.2*Math.Sin(2*Math.PI*440*i/48000)),(float)(.2*Math.Sin(2*Math.PI*440*i/48000)),out l,out r);if(i>=96000){double phase=2*Math.PI*i/48000;fr+=l*Math.Cos(phase*440);fi+=l*Math.Sin(phase*440);cr+=l*Math.Cos(phase*881);ci+=l*Math.Sin(phase*881);stereo+=Math.Abs(l-r);}}Check(Math.Sqrt(cr*cr+ci*ci)>Math.Sqrt(fr*fr+fi*fi)*.4&&stereo>1,"Crystal actual octave/stereo");log.Add("PASS Crystal actual octave-up input transposition and stereo");
 for(int route=0;route<3;route++){var f=new MasterFx{ReverbMode=2,DelayMode=3,Reverb=1,Delay=1,Size=1,Feedback=.85f,Routing=route};f.SnapRouting();double peak=0;for(int i=0;i<720000;i++){float x=i<240000?(float)(.15*Math.Sin(i*.037)+.03):0,l,r;f.Process(x,-x*.7f,out l,out r);peak=Math.Max(peak,Math.Max(Math.Abs(l),Math.Abs(r)));Check(!float.IsNaN(l)&&!float.IsInfinity(l)&&peak<3,"Max feedback route "+route);}log.Add("PASS new FX maximum feedback route="+route+" peak="+peak);f.Clear();for(int i=0;i<96000;i++){float l,r;f.Process(0,0,out l,out r);Check(l==0&&r==0,"New FX clear");}}
 var switched=new MasterFx{Reverb=1,Delay=1,Feedback=.85f,Size=1};double jump=0;float last=0;for(int i=0;i<480000;i++){if(i%24000==0){switched.CycleType(0);switched.CycleType(1);}float x=(float)(.12*Math.Sin(i*.031)),l,r;switched.Process(x,x,out l,out r);jump=Math.Max(jump,Math.Abs(l-last));last=l;}Check(jump<.1,"Effect switch click "+jump);log.Add("PASS live switching all effect types maximum sample step="+jump);
 var copy=new MasterFx{ReverbMode=2,DelayMode=3}.Copy();Check(copy.ReverbMode==2&&copy.DelayMode==3,"Export copy modes");
 using(var stream=new BinaryWriter(File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"new-fx-reference.f32")))){var fx=new MasterFx{ReverbMode=2,DelayMode=3,PsxPreset=2,CrystalPitch=-5,CrystalWindow=.203f,CrystalReverse=.42f,CrystalMix=.9f,CrystalWidth=.3f,Reverb=.8f,Delay=.7f,Size=.7f,Feedback=.72f,Time=.213f,DelaySync=false};for(int i=0;i<192000;i++){float x=(i*137%65536-32768)/32768f*.12f,l,r;fx.Process(x,-x*.71f,out l,out r);stream.Write(l);stream.Write(r);}}
 using(var form=new Pedal(true)){form.Location=new Point(-20000,-20000);form.Show();form.VerifyNewFxUi();form.Close();}log.Add("PASS effect-tab double-click selection, PS1/Crystal labels and reset");
 File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"new-fx-tests.txt"),log);
 }catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"new-fx-tests.txt"),log);Environment.ExitCode=1;}}
}
partial class Pedal {public void VerifyNewFxUi(){fxMenuPad.PerformClick();Application.DoEvents();var fx=loopers[0].Fx;fx.ReverbMode=fx.DelayMode=0;fx.Reverb=fx.Delay=.7f;var tabs=Controls.Find("MasterFxTabs",true).Single();var reverb=tabs.Controls.OfType<FxTabButton>().Single(b=>b.Effect==0);var delay=tabs.Controls.OfType<FxTabButton>().Single(b=>b.Effect==1);reverb.PerformClick();reverb.PerformClick();reverb.PerformClick();reverb.PerformClick();if(fx.ReverbMode!=2||reverb.Text!="PS1 SPU")throw new Exception("PS1 tab cycle");for(int i=0;i<6;i++)delay.PerformClick();if(fx.DelayMode!=3||delay.Text!="CRYSTAL")throw new Exception("Crystal tab cycle");using(var image=new Bitmap(ClientSize.Width,ClientSize.Height)){DrawToBitmap(image,new Rectangle(Point.Empty,ClientSize));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"new-fx-ui.png"));}var grid=Controls.Find("FxParameterGrid",true).Single();if(grid.Controls.OfType<Knob>().Count()!=7)throw new Exception("Crystal seven controls");foreach(var knob in grid.Controls.OfType<Knob>())if(knob.Bottom>grid.ClientSize.Height)throw new Exception("Crystal control clipped");
 var grain=tabs.Controls.OfType<FxTabButton>().Single(b=>b.Effect==2);fx.GrainMode=2;grain.PerformClick();if(grid.IsDisposed)grid=Controls.Find("FxParameterGrid",true).Single();if(grid.Controls.OfType<Knob>().Count()!=13)throw new Exception("Cloud thirteen controls");foreach(var knob in grid.Controls.OfType<Knob>())if(knob.Bottom>grid.ClientSize.Height)throw new Exception("Cloud control clipped");
 using(var image=new Bitmap(ClientSize.Width,ClientSize.Height)){DrawToBitmap(image,new Rectangle(Point.Empty,ClientSize));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"expanded-grain-ui.png"));}
 fx.ResetDefaults();if(fx.ReverbMode!=0||fx.DelayMode!=0)throw new Exception("New FX reset");}}
}
